// @aue/content: official content (the built-in mod), the Stronghold-compatible content interface, the registry.
// M0.5: the skeleton's stage, operators and enemies, generated by @aue/data from ArknightsGameData (data/skeleton.json).
import skeleton from '../data/skeleton.json' with { type: 'json' };
import { withTrait } from './traits.js';
import { skillDefOf } from './skills.js';

/**
 * An extracted operator record as the simulation reads it: its branch trait (职业-7) and its skill_table level as a
 * skill (技能-1).
 * @param {any} o @returns {import('@aue/sim').OperatorDef}
 */
function operatorOf(o) {
  const { skillLevel, ...rest } = o;
  return { ...withTrait(rest), ...(skillLevel ? { skill: skillDefOf(skillLevel.id, skillLevel) } : {}) };
}

/** The skeleton's content, as @aue/sim reads it. @type {import('@aue/sim').Content} */
export const skeletonContent = /** @type {any} */ ({
  ...skeleton,
  operators: Object.fromEntries(Object.entries(skeleton.operators).map(([k, o]) => [k, operatorOf(o)])),
});

/** Where the skeleton's data comes from: the ArknightsGameData commit it was generated at. */
export const skeletonSource = skeleton.source;

export { skillDefOf, skillBehaviors } from './skills.js';
export { BRANCHES, coveredBranch, withTrait } from './traits.js';
